7	/// The two write calls (`auth-signup`, `auth-login`) — exactly `{email,
8	/// password}`, no extra field (epics.md Story 1.3 AC). Posts via the shared
9	/// `ApiClient` (already anon-keyed for these two functions through
10	/// `HeaderInterceptor.anonKeyOnlyFunctions`, AD-5).
11	class AuthRemoteDataSource {
12	  AuthRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  Future<Either<Failure, AuthResponseDto>> signUp({
17	    required String email,
18	    required String password,
19	  }) =>
20	      _post('auth-signup', email: email, password: password);
21	
22	  Future<Either<Failure, AuthResponseDto>> logIn({
23	    required String email,
24	    required String password,
25	  }) =>
26	      _post('auth-login', email: email, password: password);
27	
28	  Future<Either<Failure, AuthResponseDto>> _post(
29	    String function, {
30	    required String email,
31	    required String password,
32	  }) async {
33	    final result = await _apiClient.post(
34	      function,
35	      data: {'email': email, 'password': password},
36	    );
37	    return result.flatMap((json) {
38	      try {
39	        return right(AuthResponseDto.fromJson(json));
40	      } catch (error) {
41	        // A 200 response that doesn't match the expected shape is a
42	        // client-side parse failure, never a backend-sent code — maps to
43	        // the local-only `malformedResponse` (RNF09: no exception escapes).
44	        return left(Failure.malformedResponse(message: error.toString()));
45	      }
46	    });
47	  }
48	}
