1	// The constructor keeps public named params (`remoteDataSource`,
2	// `accessTokenProvider`) distinct from the private fields they initialize,
3	// matching `api_client.dart`'s documented convention — an initializing
4	// formal isn't a clean fit here either.
5	// ignore_for_file: prefer_initializing_formals
6	import 'package:fpdart/fpdart.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../../../core/network/access_token_provider.dart';
10	import '../../domain/entities/authenticated_user.dart';
11	import '../../domain/repositories/auth_repository.dart';
12	import '../datasources/auth_remote_data_source.dart';
13	import '../models/auth_response_dto.dart';
14	
15	/// Maps the DTO to the domain entity and saves the access token *before*
16	/// returning `right(...)` — the boundary this story fixes (refresh-token
17	/// persistence is Story 1.4's job).
18	class AuthRepositoryImpl implements AuthRepository {
19	  AuthRepositoryImpl({
20	    required AuthRemoteDataSource remoteDataSource,
21	    required AccessTokenProvider accessTokenProvider,
22	  })  : _remoteDataSource = remoteDataSource,
23	        _accessTokenProvider = accessTokenProvider;
24	
25	  final AuthRemoteDataSource _remoteDataSource;
26	  final AccessTokenProvider _accessTokenProvider;
27	
28	  @override
29	  Future<Either<Failure, AuthenticatedUser>> signUp({
30	    required String email,
31	    required String password,
32	  }) =>
33	      _authenticate(
34	        () => _remoteDataSource.signUp(email: email, password: password),
35	      );
36	
37	  @override
38	  Future<Either<Failure, AuthenticatedUser>> logIn({
39	    required String email,
40	    required String password,
41	  }) =>
42	      _authenticate(
43	        () => _remoteDataSource.logIn(email: email, password: password),
44	      );
45	
46	  Future<Either<Failure, AuthenticatedUser>> _authenticate(
47	    Future<Either<Failure, AuthResponseDto>> Function() call,
48	  ) async {
49	    final result = await call();
50	    return result.match(
51	      (failure) async => left(failure),
52	      (dto) async {
53	        // A thrown platform exception (secure-storage channel failure, disk
54	        // issue, ...) must never escape unmapped (RNF09/AD-2) — if the token
55	        // can't be persisted, the call as a whole must surface as a Failure
56	        // rather than leave the caller awaiting forever. Deliberately reuses
57	        // `malformedResponse` (the only local-only variant in the closed,
58	        // exactly-14-subtype `Failure` hierarchy, AD-3) rather than adding a
59	        // new subtype just for this — it mislabels a local persistence
60	        // failure as a response-shape failure, but a dedicated subtype
61	        // isn't available without widening the closed hierarchy.
62	        try {
63	          await _accessTokenProvider.saveAccessToken(
64	            dto.data.session.accessToken,
65	          );
66	        } catch (error) {
67	          return left(Failure.malformedResponse(message: error.toString()));
68	        }
69	        return right(
70	          AuthenticatedUser(id: dto.data.user.id, email: dto.data.user.email),
71	        );
72	      },
73	    );
74	  }
75	}
