5	/// The `auth-signup`/`auth-login` response envelope
6	/// (`openapi.yaml:19-98`): `{data: {session: {...}, user: {id, email}}}`.
7	/// Field names already match the wire format's camelCase, so no `@JsonKey`
8	/// renames are needed.
9	@JsonSerializable()
10	class AuthResponseDto {
11	  const AuthResponseDto({required this.data});
12	
13	  final AuthResponseDataDto data;
14	
15	  factory AuthResponseDto.fromJson(Map<String, dynamic> json) =>
16	      _$AuthResponseDtoFromJson(json);
17	
18	  Map<String, dynamic> toJson() => _$AuthResponseDtoToJson(this);
19	}
20	
21	@JsonSerializable()
22	class AuthResponseDataDto {
23	  const AuthResponseDataDto({required this.session, required this.user});
24	
25	  final AuthSessionDto session;
26	  final AuthUserDto user;
27	
28	  factory AuthResponseDataDto.fromJson(Map<String, dynamic> json) =>
29	      _$AuthResponseDataDtoFromJson(json);
30	
31	  Map<String, dynamic> toJson() => _$AuthResponseDataDtoToJson(this);
32	}
