34	@JsonSerializable()
35	class AuthSessionDto {
36	  const AuthSessionDto({
37	    required this.accessToken,
38	    required this.refreshToken,
39	    required this.expiresIn,
40	    required this.expiresAt,
41	    required this.tokenType,
42	  });
43	
44	  final String accessToken;
45	
46	  /// Not persisted by this story — `AccessTokenProvider.saveAccessToken`
47	  /// only; refresh-token persistence is Story 1.4's job. Still decoded here
48	  /// so a missing/malformed field surfaces as `MalformedResponse` rather
49	  /// than being silently dropped.
50	  final String refreshToken;
51	  final int expiresIn;
52	  final int expiresAt;
53	  final String tokenType;
54	
55	  factory AuthSessionDto.fromJson(Map<String, dynamic> json) =>
56	      _$AuthSessionDtoFromJson(json);
57	
58	  Map<String, dynamic> toJson() => _$AuthSessionDtoToJson(this);
59	}
60	
61	@JsonSerializable()
62	class AuthUserDto {
63	  const AuthUserDto({required this.id, required this.email});
64	
65	  final String id;
66	  final String email;
67	
68	  factory AuthUserDto.fromJson(Map<String, dynamic> json) =>
69	      _$AuthUserDtoFromJson(json);
