8	/// Registers the `auth` feature into the project's single `get_it` instance
9	/// (`sl`). Called from `setupCoreDependencies()` once core infrastructure is
10	/// up, since this feature only needs `ApiClient`/`AccessTokenProvider`,
11	/// already registered there.
12	void registerAuthFeature() {
13	  sl.registerLazySingleton<AuthRemoteDataSource>(
14	    () => AuthRemoteDataSource(sl()),
15	  );
16	
17	  sl.registerLazySingleton<AuthRepository>(
18	    () => AuthRepositoryImpl(
19	      remoteDataSource: sl(),
20	      accessTokenProvider: sl<AccessTokenProvider>(),
21	    ),
22	  );
23	
24	  sl.registerLazySingleton<AuthCubit>(() => AuthCubit(sl()));
25	}
