14	class MockApiClient extends Mock implements ApiClient {}
15	
16	class MockAccessTokenProvider extends Mock implements AccessTokenProvider {}
17	
18	Map<String, dynamic> _successBody({
19	  String userId = 'user-1',
20	  String email = 'wagner@cerne.app',
21	  String accessToken = 'access-token-abc',
22	}) =>
23	    {
24	      'data': {
25	        'session': {
26	          'accessToken': accessToken,
27	          'refreshToken': 'refresh-token-abc',
28	          'expiresIn': 3600,
29	          'expiresAt': 1999999999,
30	          'tokenType': 'bearer',
31	        },
32	        'user': {'id': userId, 'email': email},
33	      },
