36	void main() {
37	  late MockApiClient mockApiClient;
38	  late MockAccessTokenProvider mockAccessTokenProvider;
39	  late AuthRepositoryImpl repository;
40	
41	  setUp(() {
42	    mockApiClient = MockApiClient();
43	    mockAccessTokenProvider = MockAccessTokenProvider();
44	    when(() => mockAccessTokenProvider.saveAccessToken(any()))
45	        .thenAnswer((_) async {});
46	    repository = AuthRepositoryImpl(
47	      remoteDataSource: AuthRemoteDataSource(mockApiClient),
48	      accessTokenProvider: mockAccessTokenProvider,
49	    );
50	  });
51	
52	  // RNF09 — the 15-scenario matrix: this story's slice is `auth-signup` and
53	  // `auth-login`, 3 failure types each.
54	  runWriteFailureMatrix<AuthenticatedUser>(
55	    endpointName: 'auth-signup',
56	    stubNetworkTimeout: () => when(
57	      () => mockApiClient.post(any(), data: any(named: 'data')),
58	    ).thenAnswer(
59	      (_) async => left(const Failure.networkTimeout(message: 'Timed out')),
60	    ),
61	    stubMalformedResponse: () => when(
62	      () => mockApiClient.post(any(), data: any(named: 'data')),
63	    ).thenAnswer((_) async => right({'unexpected': 'shape'})),
64	    stubNoConnection: () => when(
65	      () => mockApiClient.post(any(), data: any(named: 'data')),
66	    ).thenAnswer(
67	      (_) async => left(const Failure.networkOffline(message: 'Offline')),
68	    ),
69	    invoke: () => repository.signUp(
70	      email: 'wagner@cerne.app',
71	      password: 'segredo123',
72	    ),
73	  );
74	
75	  runWriteFailureMatrix<AuthenticatedUser>(
76	    endpointName: 'auth-login',
77	    stubNetworkTimeout: () => when(
78	      () => mockApiClient.post(any(), data: any(named: 'data')),
79	    ).thenAnswer(
80	      (_) async => left(const Failure.networkTimeout(message: 'Timed out')),
81	    ),
82	    stubMalformedResponse: () => when(
83	      () => mockApiClient.post(any(), data: any(named: 'data')),
84	    ).thenAnswer((_) async => right({'unexpected': 'shape'})),
85	    stubNoConnection: () => when(
86	      () => mockApiClient.post(any(), data: any(named: 'data')),
87	    ).thenAnswer(
88	      (_) async => left(const Failure.networkOffline(message: 'Offline')),
89	    ),
90	    invoke: () => repository.logIn(
91	      email: 'wagner@cerne.app',
92	      password: 'segredo123',
93	    ),
94	  );
