8	import 'features/auth/domain/repositories/session_repository.dart';
9	import 'features/auth/presentation/cubit/auth_cubit.dart';
10	import 'features/auth/presentation/screens/auth_screen.dart';
11	
12	Future<void> main() async {
13	  WidgetsFlutterBinding.ensureInitialized();
14	  try {
15	    await setupCoreDependencies();
16	  } catch (error) {
17	    debugPrint(
18	      'Cerne failed to start: could not load .env ($error). Copy '
19	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
20	      'SUPABASE_ANON_KEY before running the app.',
21	    );
22	    rethrow;
23	  }
24	  runApp(const CerneApp());
25	}
26	
27	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
28	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
29	/// epic's UX constraints).
30	///
31	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
32	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
33	/// boot (unconditional, no client-side expiry math) and the stream's first
34	/// emission decides whether the user lands on `AuthScreen` or the post-auth
35	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
36	/// shape is unchanged, and a successful signup/login still simply
37	/// pushes-replaces via `onAuthenticated`.
38	class CerneApp extends StatefulWidget {
39	  const CerneApp({super.key});
40	
41	  @override
42	  State<CerneApp> createState() => _CerneAppState();
43	}
44	
45	class _CerneAppState extends State<CerneApp> {
46	  late final SessionRepository _sessionRepository;
47	
48	  @override
49	  void initState() {
50	    super.initState();
51	    _sessionRepository = sl<SessionRepository>();
52	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
53	    // below, not through this call's return value.
54	    unawaited(_sessionRepository.restoreSession());
55	  }
56	
57	  @override
58	  Widget build(BuildContext context) {
59	    return MaterialApp(
60	      debugShowCheckedModeBanner: false,
61	      home: StreamBuilder<SessionStatus>(
62	        stream: _sessionRepository.statusStream,
63	        builder: (context, snapshot) {
64	          if (!snapshot.hasData) {
65	            // No emission yet: the brief-blank boot state RNF01's 300ms
66	            // threshold allows — no spinner/loading UI here, since the
67	            // happy path resolves well under that.
68	            return const Scaffold(backgroundColor: DesignTokens.colorSurfaceBg);
69	          }
70	          if (snapshot.data == SessionStatus.authenticated) {
71	            return const _PostAuthPlaceholder();
72	          }
73	          return AuthScreen(
74	            cubit: sl<AuthCubit>(),
75	            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
76	              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
77	            ),
78	          );
79	        },
80	      ),
81	    );
82	  }
83	}
84	
85	/// Throwaway placeholder — Story 1.6 replaces this wholesale with the real
86	/// base navigation shell. Exists only so Story 1.3 has somewhere to land
87	/// after a successful signup/login.
88	class _PostAuthPlaceholder extends StatelessWidget {
89	  const _PostAuthPlaceholder();
90	
91	  @override
92	  Widget build(BuildContext context) {
93	    return Scaffold(
94	      backgroundColor: DesignTokens.colorSurfaceBg,
95	      body: const Center(
96	        child: Text('Autenticado', style: DesignTokens.textHeadlineMd),
97	      ),
98	    );
99	  }
100	}
