10	import 'package:cerne/features/auth/domain/entities/session_status.dart';
11	
12	class MockAuthRemoteDataSource extends Mock implements AuthRemoteDataSource {}
13	
14	class MockAccessTokenProvider extends Mock implements AccessTokenProvider {}
15	
16	const _newSession = AuthSessionDto(
17	  accessToken: 'new-access-token',
18	  refreshToken: 'new-refresh-token',
19	  expiresIn: 3600,
20	  expiresAt: 1999999999,
21	  tokenType: 'bearer',
22	);
23	
24	void main() {
25	  late MockAuthRemoteDataSource mockRemoteDataSource;
26	  late MockAccessTokenProvider mockAccessTokenProvider;
27	  late SessionRepositoryImpl repository;
28	
29	  setUp(() {
30	    mockRemoteDataSource = MockAuthRemoteDataSource();
31	    mockAccessTokenProvider = MockAccessTokenProvider();
32	    when(
33	      () => mockAccessTokenProvider.saveSession(
34	        accessToken: any(named: 'accessToken'),
35	        refreshToken: any(named: 'refreshToken'),
36	      ),
37	    ).thenAnswer((_) async {});
38	    when(() => mockAccessTokenProvider.clearSession()).thenAnswer((_) async {});
39	    repository = SessionRepositoryImpl(
40	      remoteDataSource: mockRemoteDataSource,
41	      accessTokenProvider: mockAccessTokenProvider,
42	    );
43	  });
44	
45	  /// Subscribes before [restoreSession] runs (required for a broadcast
46	  /// stream) and drains the microtask queue afterwards so the event posted
47	  /// by `_statusController.add(...)` has definitely been delivered by the
48	  /// time this returns — same rationale as `auth_cubit_test.dart`'s
49	  /// `_emittedDuring` helper.
50	  Future<List<SessionStatus>> emittedDuring(Future<void> Function() act) async {
51	    final emitted = <SessionStatus>[];
52	    final subscription = repository.statusStream.listen(emitted.add);
53	    await act();
54	    await Future<void>.delayed(Duration.zero);
55	    await subscription.cancel();
56	    return emitted;
57	  }
58	
59	  group('cold boot, valid refresh token', () {
60	    test('auth-refresh succeeds -> new pair saved, stream emits '
61	        'authenticated, Right(unit) returned', () async {
62	      when(() => mockAccessTokenProvider.readRefreshToken())
63	          .thenAnswer((_) async => 'stored-refresh-token');
64	      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
65	          .thenAnswer((_) async => right(_newSession));
66	
67	      Either<Failure, Unit>? result;
68	      final emitted = await emittedDuring(() async {
69	        result = await repository.restoreSession();
70	      });
71	
72	      expect(emitted, [SessionStatus.authenticated]);
73	      expect(result!.isRight(), isTrue);
74	      verify(
75	        () => mockAccessTokenProvider.saveSession(
76	          accessToken: 'new-access-token',
77	          refreshToken: 'new-refresh-token',
78	        ),
79	      ).called(1);
80	      verifyNever(() => mockAccessTokenProvider.clearSession());
81	    });
82	  });
83	
84	  group('cold boot, no stored session', () {
85	    test('no refresh token -> no network call, stream emits unauthenticated '
86	        'immediately', () async {
87	      when(() => mockAccessTokenProvider.readRefreshToken())
88	          .thenAnswer((_) async => null);
89	
90	      Either<Failure, Unit>? result;
91	      final emitted = await emittedDuring(() async {
92	        result = await repository.restoreSession();
93	      });
94	
95	      expect(emitted, [SessionStatus.unauthenticated]);
96	      expect(result!.isLeft(), isTrue);
97	      verifyNever(() => mockRemoteDataSource.refresh(any()));
98	      verifyNever(
99	        () => mockAccessTokenProvider.saveSession(
100	          accessToken: any(named: 'accessToken'),
101	          refreshToken: any(named: 'refreshToken'),
102	        ),
103	      );
104	      verifyNever(() => mockAccessTokenProvider.clearSession());
105	    });
106	  });
107	
108	  group('cold boot, dead refresh token', () {
109	    test(
110	      'backend returns AUTH_EXPIRED -> session cleared, stream emits '
111	      'unauthenticated, silently (Left surfaced to the caller only)',
112	      () async {
113	        when(() => mockAccessTokenProvider.readRefreshToken())
114	            .thenAnswer((_) async => 'dead-refresh-token');
115	        when(
116	          () => mockRemoteDataSource.refresh('dead-refresh-token'),
117	        ).thenAnswer(
118	          (_) async =>
119	              left(const Failure.authExpired(message: 'Refresh token dead')),
120	        );
121	
122	        Either<Failure, Unit>? result;
123	        final emitted = await emittedDuring(() async {
124	          result = await repository.restoreSession();
125	        });
126	
127	        expect(emitted, [SessionStatus.unauthenticated]);
128	        expect(result!.isLeft(), isTrue);
129	        result!.match(
130	          (failure) => expect(failure, isA<AuthExpired>()),
131	          (_) => fail('expected Left'),
132	        );
133	        verify(() => mockAccessTokenProvider.clearSession()).called(1);
134	      },
135	    );
136	
137	    test('backend returns AUTH_INVALID -> session cleared, stream emits '
138	        'unauthenticated', () async {
139	      when(() => mockAccessTokenProvider.readRefreshToken())
140	          .thenAnswer((_) async => 'invalid-refresh-token');
141	      when(
142	        () => mockRemoteDataSource.refresh('invalid-refresh-token'),
143	      ).thenAnswer(
144	        (_) async =>
145	            left(const Failure.authInvalid(message: 'Refresh token invalid')),
146	      );
147	
148	      final emitted = await emittedDuring(() async {
149	        await repository.restoreSession();
150	      });
151	
152	      expect(emitted, [SessionStatus.unauthenticated]);
153	      verify(() => mockAccessTokenProvider.clearSession()).called(1);
154	    });
155	  });
156	
157	  group('cold boot, offline', () {
158	    test('no connectivity -> stream emits unauthenticated (fail-closed), '
159	        'storage left untouched', () async {
160	      when(() => mockAccessTokenProvider.readRefreshToken())
161	          .thenAnswer((_) async => 'stored-refresh-token');
162	      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
163	          .thenAnswer(
164	            (_) async => left(const Failure.networkOffline(message: 'Offline')),
165	          );
166	
167	      Either<Failure, Unit>? result;
168	      final emitted = await emittedDuring(() async {
169	        result = await repository.restoreSession();
170	      });
171	
172	      expect(emitted, [SessionStatus.unauthenticated]);
173	      expect(result!.isLeft(), isTrue);
174	      result!.match(
175	        (failure) => expect(failure, isA<NetworkOffline>()),
176	        (_) => fail('expected Left'),
177	      );
178	      // Fail-closed, but the stored token is NOT cleared — only a
179	      // backend-confirmed dead token (AUTH_EXPIRED/AUTH_INVALID) clears it.
180	      verifyNever(() => mockAccessTokenProvider.clearSession());
181	    });
182	  });
183	}
