1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:fpdart/fpdart.dart' hide State;
5	
6	import 'core/design_tokens.dart';
7	import 'core/di/injection_container.dart';
8	import 'core/failure/failure.dart';
9	import 'features/auth/domain/entities/session_status.dart';
10	import 'features/auth/domain/repositories/session_repository.dart';
11	import 'features/auth/presentation/cubit/auth_cubit.dart';
12	import 'features/auth/presentation/screens/auth_screen.dart';
13	
14	Future<void> main() async {
15	  WidgetsFlutterBinding.ensureInitialized();
16	  try {
17	    await setupCoreDependencies();
18	  } catch (error) {
19	    debugPrint(
20	      'Cerne failed to start: could not load .env ($error). Copy '
21	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
22	      'SUPABASE_ANON_KEY before running the app.',
23	    );
24	    rethrow;
25	  }
26	  runApp(const CerneApp());
27	}
28	
29	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
30	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
31	/// epic's UX constraints).
32	///
33	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
34	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
35	/// boot (unconditional, no client-side expiry math) and the stream's first
36	/// emission decides whether the user lands on `AuthScreen` or the post-auth
37	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
38	/// shape is unchanged, and a successful signup/login still simply
39	/// pushes-replaces via `onAuthenticated`.
40	class CerneApp extends StatefulWidget {
41	  const CerneApp({super.key});
42	
43	  @override
44	  State<CerneApp> createState() => _CerneAppState();
45	}
46	
47	class _CerneAppState extends State<CerneApp> {
48	  late final SessionRepository _sessionRepository;
49	
50	  @override
51	  void initState() {
52	    super.initState();
53	    _sessionRepository = sl<SessionRepository>();
54	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
55	    // below, not through this call's return value. `restoreSession()`
56	    // already maps every internal failure to `Left`/an `unauthenticated`
57	    // emission and never throws, but swallowing any error here anyway is
58	    // cheap insurance against it otherwise surfacing as an unhandled zone
59	    // exception.
60	    unawaited(
61	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
62	    );
63	  }
64	
65	  // `catchError`'s handler must still complete the Future with a value of
66	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
67	  // handler would try to complete it with `null`, which isn't assignable
68	  // to that non-nullable type and would itself throw.
69	  static Either<Failure, Unit> _asUnauthenticated(
70	    Object error,
71	    StackTrace stackTrace,
72	  ) {
73	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
74	    return left(Failure.malformedResponse(message: error.toString()));
75	  }
76	
77	  @override
78	  Widget build(BuildContext context) {
79	    return MaterialApp(
80	      debugShowCheckedModeBanner: false,
81	      home: StreamBuilder<SessionStatus>(
82	        stream: _sessionRepository.statusStream,
83	        builder: (context, snapshot) {
84	          if (!snapshot.hasData) {
85	            // No emission yet: brief-blank for the happy path (RNF01's
86	            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
87	            // spinner once the wait actually crosses that.
88	            return const _BootLoadingScreen();
89	          }
90	          if (snapshot.data == SessionStatus.authenticated) {
91	            return const _PostAuthPlaceholder();
92	          }
93	          return AuthScreen(
94	            cubit: sl<AuthCubit>(),
95	            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
96	              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
97	            ),
98	          );
99	        },
100	      ),
101	    );
102	  }
103	}
104	
105	/// Throwaway placeholder — Story 1.6 replaces this wholesale with the real
106	/// base navigation shell. Exists only so Story 1.3 has somewhere to land
107	/// after a successful signup/login.
108	class _PostAuthPlaceholder extends StatelessWidget {
109	  const _PostAuthPlaceholder();
110	
111	  @override
112	  Widget build(BuildContext context) {
113	    return Scaffold(
114	      backgroundColor: DesignTokens.colorSurfaceBg,
115	      body: const Center(
116	        child: Text('Autenticado', style: DesignTokens.textHeadlineMd),
117	      ),
118	    );
119	  }
120	}
121	
122	/// Shown while `statusStream` has no data yet. Blank for the happy path
123	/// (RNF01: no loading UI below 300ms), but surfaces a centered spinner once
124	/// the wait crosses that threshold — `auth-refresh` is retried by
125	/// `RetryInterceptor` on `NETWORK_TIMEOUT`/`NETWORK_OFFLINE`, so a slow or
126	/// offline boot could otherwise leave the screen looking frozen for several
127	/// seconds with zero feedback. Kept as a private, inline, one-off widget
128	/// (no new shared-widget param) — same minimal-treatment convention Story
129	/// 1.3's submit button uses for its own >300ms affordance.
130	class _BootLoadingScreen extends StatefulWidget {
131	  const _BootLoadingScreen();
132	
133	  @override
134	  State<_BootLoadingScreen> createState() => _BootLoadingScreenState();
135	}
136	
137	class _BootLoadingScreenState extends State<_BootLoadingScreen> {
138	  static const _threshold = Duration(milliseconds: 300);
139	
140	  bool _showIndicator = false;
141	  Timer? _timer;
142	
143	  @override
144	  void initState() {
145	    super.initState();
146	    _timer = Timer(_threshold, () {
147	      if (mounted) {
148	        setState(() => _showIndicator = true);
149	      }
150	    });
151	  }
152	
153	  @override
154	  void dispose() {
155	    _timer?.cancel();
156	    super.dispose();
157	  }
158	
159	  @override
160	  Widget build(BuildContext context) {
161	    return Scaffold(
162	      backgroundColor: DesignTokens.colorSurfaceBg,
163	      body: Center(
164	        child: _showIndicator
165	            ? const CircularProgressIndicator(color: DesignTokens.colorPrimary)
166	            : const SizedBox.shrink(),
167	      ),
168	    );
169	  }
170	}
