1	// The constructor keeps public named params (`remoteDataSource`,
2	// `accessTokenProvider`) distinct from the private fields they initialize,
3	// matching `auth_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../../../../core/network/access_token_provider.dart';
11	import '../../domain/entities/session_status.dart';
12	import '../../domain/repositories/session_repository.dart';
13	import '../datasources/auth_remote_data_source.dart';
14	
15	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
16	/// [restoreSession] is unconditional — no client-side expiry math — and
17	/// covers the I/O matrix (spec-1-4):
18	/// - no stored refresh token -> no network call, emits `unauthenticated`
19	///   immediately.
20	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
21	///   emits `authenticated`.
22	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
23	///   token) -> `clearSession`, emits `unauthenticated`.
24	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
25	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
26	///   retries naturally.
27	class SessionRepositoryImpl implements SessionRepository {
28	  SessionRepositoryImpl({
29	    required AuthRemoteDataSource remoteDataSource,
30	    required AccessTokenProvider accessTokenProvider,
31	  }) : _remoteDataSource = remoteDataSource,
32	       _accessTokenProvider = accessTokenProvider;
33	
34	  final AuthRemoteDataSource _remoteDataSource;
35	  final AccessTokenProvider _accessTokenProvider;
36	  final StreamController<SessionStatus> _statusController =
37	      StreamController<SessionStatus>.broadcast();
38	
39	  /// The last status emitted, so a consumer that subscribes *after* the
40	  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
41	  /// listener) still sees current state immediately rather than nothing
42	  /// until the next change — see [statusStream].
43	  SessionStatus? _lastStatus;
44	
45	  @override
46	  Stream<SessionStatus> get statusStream {
47	    // `Stream.multi` runs this callback once per listener (and, with
48	    // `isBroadcast: true`, supports more than one simultaneously) — each
49	    // new listener synchronously gets the cached last status (if any)
50	    // before being attached to the live broadcast controller for whatever
51	    // comes next. This is this story's whole reason to not just expose
52	    // `_statusController.stream` directly: a plain broadcast stream only
53	    // ever delivers *future* events to a listener that joins late.
54	    return Stream<SessionStatus>.multi((controller) {
55	      final last = _lastStatus;
56	      if (last != null) {
57	        controller.add(last);
58	      }
59	      final subscription = _statusController.stream.listen(
60	        controller.add,
61	        onError: controller.addError,
62	        onDone: controller.close,
63	      );
64	      controller.onCancel = subscription.cancel;
65	    }, isBroadcast: true);
66	  }
67	
68	  void _emit(SessionStatus status) {
69	    _lastStatus = status;
70	    _statusController.add(status);
71	  }
72	
73	  @override
74	  Future<Either<Failure, Unit>> restoreSession() async {
75	    String? refreshToken;
76	    try {
77	      refreshToken = await _accessTokenProvider.readRefreshToken();
78	    } catch (error) {
79	      // A thrown platform exception from the native secure-storage channel
80	      // must never escape unmapped (RNF09) — fail closed, same as any other
81	      // unreadable session.
82	      _emit(SessionStatus.unauthenticated);
83	      return left(Failure.malformedResponse(message: error.toString()));
84	    }
85	
86	    if (refreshToken == null) {
87	      // Fresh install / post-logout: no network call at all.
88	      _emit(SessionStatus.unauthenticated);
89	      return left(
90	        const Failure.authExpired(message: 'No stored session to restore'),
91	      );
92	    }
93	
94	    final result = await _remoteDataSource.refresh(refreshToken);
95	    return result.match(
96	      (failure) async {
97	        // Only a backend-confirmed dead token clears storage; any other
98	        // failure (offline, timeout, malformed response, ...) leaves it
99	        // untouched so the next boot retries naturally.
100	        if (failure is AuthExpired || failure is AuthInvalid) {
101	          try {
102	            await _accessTokenProvider.clearSession();
103	          } catch (_) {
104	            // Best-effort clear — the session is already being treated as
105	            // unauthenticated below regardless of whether this succeeds.
106	          }
107	        }
108	        _emit(SessionStatus.unauthenticated);
109	        return left(failure);
110	      },
111	      (session) async {
112	        try {
113	          await _accessTokenProvider.saveSession(
114	            accessToken: session.accessToken,
115	            refreshToken: session.refreshToken,
116	          );
117	        } catch (error) {
118	          _emit(SessionStatus.unauthenticated);
119	          return left(Failure.malformedResponse(message: error.toString()));
120	        }
121	        _emit(SessionStatus.authenticated);
122	        return right(unit);
123	      },
124	    );
125	  }
126	
127	  @override
128	  Future<void> dispose() => _statusController.close();
129	}
130
